// Month-jump enhanced-navigation acceptance (Test Author handoff).
//
// Executes the SHIPPED binder (public/islands/events-calendar.js) in a fixture
// DOM with intercepted fetch: no browser, DB, network or new dependency.
// RED on arrival: the binder wires clicks, search input/submit and popstate,
// but no month-jump submit — each RED test fails with zero jump requests.
// CONTROL tests pass before and after; they pin the existing ownership the
// Builder must reuse (fragment fetch + zones + pushState + focus restore).
// Builder: wire the jump form into load(); do NOT edit this file. Suggested
// wiring (not pinned): submit → cancelDebounce → load(jumpUrl, true,
// {skeleton, syncInput, control: submitter, focus: '[data-testid=
// "calendar-month-jump-submit"]'}) so success lands in the new form and
// failure restores the origin submitter through the existing focus paths.
import { readFileSync } from "node:fs";
import { runInNewContext } from "node:vm";
import { URL as NodeURL, URLSearchParams as NodeURLSearchParams } from "node:url";
import { afterEach, describe, expect, it, vi } from "vitest";

const binder = readFileSync(
  new NodeURL("../public/islands/events-calendar.js", import.meta.url),
  "utf8",
);
const ORIGIN = "https://calendar.example.test";
const ENTRY = "/events?view=calendar&month=2026-10&past=1";
const LIVE_IDS = [
  "events-view-status",
  "events-search-status",
  "events-past-status",
  "calendar-month-status",
];
const LOAD_ERROR = "Calendar unavailable. Try again.";
const JUMP_FORM_TESTID = "calendar-month-jump";
const JUMP_SUBMIT_TESTID = "calendar-month-jump-submit";
const THIS_MONTH_TESTID = "calendar-this-month";

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: Error) => void;
  const promise = new Promise<T>((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return { promise, resolve, reject };
}

async function flush(rounds = 25): Promise<void> {
  for (let i = 0; i < rounds; i++) await Promise.resolve();
}

function browser(entry = ENTRY) {
  let activeElement: Element;
  const focusListeners = new Set<(event: { target: Element }) => void>();
  class Element {
    parent: Element | null = null;
    childNodes: Element[] = [];
    hidden = false;
    textContent = "";
    value = "";
    content = "";
    dataset: Record<string, string> = {};
    attributes = new Map<string, string>();
    listeners = new Map<string, ((event: any) => void)[]>();
    constructor(
      readonly tag = "div",
      attrs: Record<string, string> = {},
    ) {
      for (const [key, value] of Object.entries(attrs)) this.attributes.set(key, value);
    }
    get href() {
      return new URL(this.getAttribute("href") || "/events", ORIGIN).href;
    }
    set href(value: string) {
      this.setAttribute("href", value);
    }
    get hash() {
      return new URL(this.href).hash;
    }
    get target() {
      return this.getAttribute("target") || "";
    }
    getAttribute(key: string) {
      return this.attributes.get(key) ?? null;
    }
    setAttribute(key: string, value: string) {
      this.attributes.set(key, value);
    }
    removeAttribute(key: string) {
      this.attributes.delete(key);
    }
    hasAttribute(key: string) {
      return this.attributes.has(key);
    }
    matches(selector: string): boolean {
      if (selector.startsWith("#")) return this.getAttribute("id") === selector.slice(1);
      if (selector === "[hidden]") return this.hidden;
      const attr = /^(\w+)?\[([^=\]]+)(?:="([^"]*)")?\]$/.exec(selector);
      return attr
        ? (!attr[1] || this.tag === attr[1]) &&
            this.hasAttribute(attr[2]!) &&
            (attr[3] === undefined || this.getAttribute(attr[2]!) === attr[3])
        : this.tag === selector;
    }
    closest(selector: string): Element | null {
      return this.matches(selector) ? this : (this.parent?.closest(selector) ?? null);
    }
    contains(node: Element | undefined): boolean {
      return node === this || this.childNodes.some((child) => child.contains(node));
    }
    querySelectorAll(selector: string): Element[] {
      return this.childNodes.flatMap((child) => [
        ...(child.matches(selector) ? [child] : []),
        ...child.querySelectorAll(selector),
      ]);
    }
    querySelector(selector: string) {
      return this.querySelectorAll(selector)[0] ?? null;
    }
    replaceChildren(...children: Element[]) {
      if (this.childNodes.some((child) => child.contains(activeElement))) activeElement = body;
      this.childNodes.forEach((child) => {
        child.parent = null;
      });
      this.childNodes = children;
      children.forEach((child) => {
        child.parent = this;
      });
    }
    focus() {
      if (body.contains(this) && !this.closest("[hidden]") && activeElement !== this) {
        activeElement = this;
        focusListeners.forEach((fn) => fn({ target: this }));
      }
    }
    addEventListener(type: string, fn: (event: any) => void) {
      this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
    }
    fire(type: string, event: any = {}) {
      this.listeners.get(type)?.forEach((fn) => fn(event));
    }
  }
  const node = (tag: string, attrs: Record<string, string> = {}) => new Element(tag, attrs);
  const body = node("body");
  activeElement = body;
  const root = node("section", { "data-island": "events-calendar" });
  root.dataset.view = "calendar";
  root.dataset.month = "2026-10";
  root.dataset.past = "1";
  root.dataset.loadError = LOAD_ERROR;
  root.dataset.searchMaxLength = "255";
  root.dataset.searchTooLong = "Search query must be 255 characters or fewer.";

  const heading = node("h1", { id: "events-heading", tabindex: "-1" });
  const searchInput = node("input", { "data-testid": "events-search" });
  const searchForm = node("form");
  const zones = Object.fromEntries(
    ["head", "actions", "miss", "content"].map((name) => [
      name,
      node("div", { "data-cal-zone": name }),
    ]),
  );
  searchForm.replaceChildren(searchInput, zones.actions!);
  const skeleton = node("div", { "data-testid": "events-loading" });
  skeleton.hidden = true;
  const feedback = node("p", { "data-cal-feedback": "" });
  const canonical = node("link", { rel: "canonical", href: ORIGIN + entry });
  const og = node("meta", { property: "og:url", content: ORIGIN + entry });

  // Month controls mirror the SSR contract pinned in
  // calendar-month-jump-acceptance.test.ts: This month anchor + GET form.
  const thisMonth = (month: string, past: string) =>
    node("a", {
      "data-testid": THIS_MONTH_TESTID,
      href: `/events?view=calendar&month=${month}${past === "1" ? "&past=1" : ""}`,
    });
  const jumpForm = (month: string, past: string) => {
    const form = node("form", {
      "data-testid": JUMP_FORM_TESTID,
      method: "get",
      action: "/events",
    });
    const label = node("label", { for: "month-jump-input" });
    label.textContent = "Jump to month";
    const input = node("input", {
      id: "month-jump-input",
      type: "month",
      name: "month",
      min: "0001-01",
      max: "9999-12",
    });
    input.value = month;
    const view = node("input", { type: "hidden", name: "view" });
    view.value = "calendar";
    const children = [label, input, view];
    if (past === "1") {
      const pastField = node("input", { type: "hidden", name: "past" });
      pastField.value = "1";
      children.push(pastField);
    }
    const submit = node("button", { type: "submit", "data-testid": JUMP_SUBMIT_TESTID });
    submit.textContent = "Go";
    children.push(submit);
    form.replaceChildren(...children);
    return form;
  };
  const marker = (text: string) => {
    const m = node("div");
    m.textContent = text;
    return m;
  };
  zones.content!.replaceChildren(
    node("a", {
      "aria-label": "Previous month",
      href: "/events?view=calendar&month=2026-09&past=1",
    }),
    thisMonth("2026-11", "1"),
    jumpForm("2026-10", "1"),
    marker("initial content"),
  );
  for (const name of ["head", "actions", "miss"]) {
    zones[name]!.replaceChildren(marker(`initial ${name}`));
  }
  root.replaceChildren(
    heading,
    ...LIVE_IDS.map((id) => node("p", { "data-testid": id })),
    zones.head!,
    searchForm,
    zones.miss!,
    skeleton,
    zones.content!,
    feedback,
  );
  body.replaceChildren(root, node("button"));

  const history: string[] = [];
  const reloads: string[] = [];
  const location = {
    href: ORIGIN + entry,
    origin: ORIGIN,
    assign: (href: string) => reloads.push(href),
  };
  const requests: {
    url: string;
    init: { signal: AbortSignal; headers?: Record<string, string> };
    response: ReturnType<typeof deferred<{ ok: boolean; text: () => Promise<string> }>>;
  }[] = [];
  const pages = new Map<string, { querySelector: (selector: string) => unknown }>();
  let click!: (event: any) => void;
  let popstate!: () => void;

  // Minimal FormData over the fixture form so either binder implementation
  // (field reads or form serialization) resolves the same jump params.
  class FixtureFormData {
    #fields: [string, string][];
    constructor(form: Element) {
      this.#fields = form
        .querySelectorAll("input")
        .filter((input) => input.getAttribute("name"))
        .map((input) => [input.getAttribute("name")!, input.value]);
    }
    get(name: string) {
      return this.#fields.find(([key]) => key === name)?.[1] ?? null;
    }
    *entries(): Generator<[string, string]> {
      yield* this.#fields;
    }
    [Symbol.iterator]() {
      return this.entries();
    }
  }

  runInNewContext(
    binder,
    {
      URL: NodeURL,
      URLSearchParams: NodeURLSearchParams,
      FormData: FixtureFormData,
      AbortController,
      setTimeout,
      clearTimeout,
      document: {
        querySelector: (selector: string) =>
          selector.startsWith("link")
            ? canonical
            : selector.startsWith("meta")
              ? og
              : selector === '[data-island="events-calendar"]'
                ? root
                : null,
        importNode: (child: Element) => child,
        addEventListener: (type: string, fn: (event: { target: Element }) => void) => {
          if (type === "focusin") focusListeners.add(fn);
        },
        removeEventListener: (type: string, fn: (event: { target: Element }) => void) => {
          if (type === "focusin") focusListeners.delete(fn);
        },
        get activeElement() {
          return activeElement;
        },
      },
      window: {
        location,
        history: {
          pushState(_state: unknown, _title: string, path: string) {
            history.push(path);
            location.href = ORIGIN + path;
          },
        },
        addEventListener(_type: string, listener: () => void) {
          popstate = listener;
        },
      },
      DOMParser: class {
        parseFromString(html: string) {
          return pages.get(html);
        }
      },
      fetch: (url: string, init: { signal: AbortSignal; headers?: Record<string, string> }) => {
        const response = deferred<{ ok: boolean; text: () => Promise<string> }>();
        requests.push({ url, init, response });
        return response.promise;
      },
    },
    { filename: "public/islands/events-calendar.js" },
  );
  // The binder attached its click listener during evaluation; capture it.
  click = root.listeners.get("click")?.[0] as (event: any) => void;

  function page(month: string, opts: { view?: string; past?: string; searchValue?: string } = {}) {
    const view = opts.view ?? "calendar";
    const past = opts.past ?? "1";
    const searchValue = opts.searchValue ?? "";
    const sources = ["head", "actions", "miss", "content"].map((name) => {
      const zone = node("div", { "data-cal-zone": name });
      if (name === "content") {
        // This month is clock-derived, so every response page names the same one.
        zone.replaceChildren(
          thisMonth("2026-11", past),
          jumpForm(month, past),
          marker(`content:${month}`),
        );
      } else {
        zone.replaceChildren(marker(`${name}:${month}`));
      }
      return zone;
    });
    const key = `page:${month}:${requests.length}`;
    const path = `/events?${past === "1" ? "past=1&" : ""}view=${view}&month=${month}`;
    pages.set(key, {
      querySelector(selector: string) {
        if (selector === '[data-island="events-calendar"]') {
          // Zones only answer their own selector; any other selector (for example
          // the card sign-in links the island validates) matches nothing, as in a DOM.
          return {
            dataset: { view, month, past },
            querySelectorAll: (selector: string) => (selector === "[data-cal-zone]" ? sources : []),
          };
        }
        if (selector.startsWith("link")) return { href: ORIGIN + path };
        if (selector === '[data-testid="events-search"]') {
          return { getAttribute: (name: string) => (name === "value" ? searchValue : null) };
        }
        const id = /data-testid="([^"]+)"/.exec(selector)?.[1];
        if (id && LIVE_IDS.includes(id)) return { textContent: `${month} ${id}` };
        return null;
      },
    });
    return key;
  }

  const zoneText = (name: string) =>
    zones[name]!.childNodes.map((child) => child.textContent).join("|");
  const paramsOf = (url: string) => {
    const parsed = new NodeURL(url, ORIGIN);
    return { pathname: parsed.pathname, params: parsed.searchParams };
  };

  return {
    root,
    zones,
    skeleton,
    feedback,
    searchInput,
    searchForm,
    history,
    reloads,
    location,
    requests,
    page,
    zoneText,
    paramsOf,
    jumpForm: () => zones.content!.querySelector(`[data-testid="${JUMP_FORM_TESTID}"]`)!,
    jumpInput: () => zones.content!.querySelector('[name="month"]')!,
    jumpSubmit: () => zones.content!.querySelector(`[data-testid="${JUMP_SUBMIT_TESTID}"]`)!,
    thisMonth: () => zones.content!.querySelector(`[data-testid="${THIS_MONTH_TESTID}"]`)!,
    active: () => activeElement,
    async resolve(index: number, key: string, ok = true) {
      requests[index]!.response.resolve({ ok, text: async () => key });
      await flush();
    },
    async reject(index: number, error = new Error("boom")) {
      requests[index]!.response.reject(error);
      await flush();
    },
    click(link: Element, keyboard = true) {
      if (keyboard) link.focus();
      let prevented = false;
      click({
        button: 0,
        detail: keyboard ? 0 : 1,
        target: { closest: (selector: string) => (selector === "a" ? link : null) },
        preventDefault() {
          prevented = true;
        },
      });
      return prevented;
    },
    submitJump() {
      const form = this.jumpForm();
      const submitter = this.jumpSubmit();
      submitter.focus();
      let prevented = false;
      form.fire("submit", {
        submitter,
        preventDefault() {
          prevented = true;
        },
      });
      return { prevented, submitter };
    },
    back(path: string) {
      location.href = ORIGIN + path;
      popstate();
    },
  };
}

afterEach(() => vi.useRealTimers());

describe("enhanced month jump", () => {
  it("submits through the fragment flow and commits the chosen month URL", async () => {
    const t = browser();
    t.jumpInput().value = "2026-12";
    const { prevented, submitter } = t.submitJump();
    expect(prevented).toBe(true);
    expect(t.requests).toHaveLength(1);
    const sent = t.paramsOf(t.requests[0]!.url);
    expect(sent.pathname).toBe("/events");
    expect(sent.params.get("view")).toBe("calendar");
    expect(sent.params.get("month")).toBe("2026-12");
    expect(sent.params.get("past")).toBe("1");
    expect(sent.params.get("q")).toBeNull();
    expect(t.requests[0]!.init.headers).toMatchObject({
      accept: "text/html",
      "x-two-island": "events-calendar",
    });
    expect(t.skeleton.hidden).toBe(false);
    await t.resolve(0, t.page("2026-12"));
    expect(t.zoneText("content")).toContain("content:2026-12");
    expect(t.history).toHaveLength(1);
    const pushed = t.paramsOf(t.history[0]!);
    expect(pushed.params.get("month")).toBe("2026-12");
    expect(pushed.params.get("view")).toBe("calendar");
    expect(pushed.params.get("past")).toBe("1");
    expect(t.skeleton.hidden).toBe(true);
    expect(t.feedback.textContent).toBe("");
    expect(t.root.dataset.month).toBe("2026-12");
    expect(t.active()).not.toBeUndefined();
    // Focus lands in the new jump form — never lost to body on a swap.
    expect(t.jumpForm().contains(t.active())).toBe(true);
    expect(t.active()).not.toBe(submitter);
  });

  it("keeps the last good grid and restores the submitter on failure", async () => {
    const t = browser();
    t.jumpInput().value = "2026-12";
    const { prevented, submitter } = t.submitJump();
    expect(prevented).toBe(true);
    expect(t.requests).toHaveLength(1);
    await t.reject(0);
    expect(t.feedback.textContent).toBe(LOAD_ERROR);
    expect(t.zoneText("content")).toContain("initial content");
    expect(t.history).toHaveLength(0);
    expect(t.reloads).toHaveLength(0);
    expect(t.skeleton.hidden).toBe(true);
    expect(t.active()).toBe(submitter);
  });

  it("lets a newer jump supersede an in-flight one", async () => {
    const t = browser();
    t.jumpInput().value = "2026-12";
    expect(t.submitJump().prevented).toBe(true);
    t.jumpInput().value = "2027-01";
    expect(t.submitJump().prevented).toBe(true);
    expect(t.requests).toHaveLength(2);
    expect(t.requests[0]!.init.signal.aborted).toBe(true);
    await t.resolve(1, t.page("2027-01"));
    expect(t.history).toHaveLength(1);
    expect(t.paramsOf(t.history[0]!).params.get("month")).toBe("2027-01");
    // The stale response lands late and must not clobber the committed grid.
    await t.resolve(0, t.page("2026-12"));
    expect(t.history).toHaveLength(1);
    expect(t.zoneText("content")).toContain("content:2027-01");
    expect(t.root.dataset.month).toBe("2027-01");
  });

  it("cancels a pending search instead of racing it", async () => {
    vi.useFakeTimers();
    const t = browser();
    t.searchInput.value = "raid";
    t.searchInput.fire("input", {});
    t.jumpInput().value = "2026-12";
    expect(t.submitJump().prevented).toBe(true);
    await vi.advanceTimersByTimeAsync(500);
    expect(t.requests).toHaveLength(1);
    expect(t.paramsOf(t.requests[0]!.url).params.get("month")).toBe("2026-12");
  });

  it("commits the server fallback grid for an out-of-range jump without looping", async () => {
    const t = browser();
    // Native min/max normally blocks this; the property set simulates a
    // bypass (or an older month grammar) reaching the fragment flow.
    t.jumpInput().value = "0000-01";
    expect(t.submitJump().prevented).toBe(true);
    expect(t.requests).toHaveLength(1);
    expect(t.paramsOf(t.requests[0]!.url).params.get("month")).toBe("0000-01");
    // The server answers the fallback month, like the no-JS full navigation.
    await t.resolve(0, t.page("2026-10", { past: "1" }));
    expect(t.zoneText("content")).toContain("content:2026-10");
    expect(t.history).toHaveLength(1);
    expect(t.requests).toHaveLength(1);
    expect(t.reloads).toHaveLength(0);
  });

  it("restores the prior month on back without pushing a stale URL", async () => {
    const t = browser();
    t.jumpInput().value = "2026-12";
    expect(t.submitJump().prevented).toBe(true);
    await t.resolve(0, t.page("2026-12"));
    expect(t.history).toHaveLength(1);
    t.back(ENTRY);
    expect(t.requests).toHaveLength(2);
    expect(t.paramsOf(t.requests[1]!.url).params.get("month")).toBe("2026-10");
    await t.resolve(1, t.page("2026-10"));
    expect(t.history).toHaveLength(1);
    expect(t.zoneText("content")).toContain("content:2026-10");
    expect(t.root.dataset.month).toBe("2026-10");
  });

  it("CONTROL: the This month anchor upgrades through the existing click path", async () => {
    const t = browser();
    expect(t.click(t.thisMonth())).toBe(true);
    expect(t.requests).toHaveLength(1);
    const sent = t.paramsOf(t.requests[0]!.url);
    expect(sent.params.get("month")).toBe("2026-11");
    expect(sent.params.get("view")).toBe("calendar");
    expect(sent.params.get("past")).toBe("1");
    await t.resolve(0, t.page("2026-11"));
    expect(t.history).toHaveLength(1);
    expect(t.active()).toBe(t.thisMonth());
  });

  it("CONTROL: typing in the month box schedules no island search", async () => {
    vi.useFakeTimers();
    const t = browser();
    t.jumpInput().value = "2027-05";
    t.jumpInput().fire("input", {});
    await vi.advanceTimersByTimeAsync(500);
    await flush();
    expect(t.requests).toHaveLength(0);
  });

  it("CONTROL: search from the month view still forces the list view", async () => {
    vi.useFakeTimers();
    const t = browser();
    t.searchInput.value = "raid";
    t.searchInput.fire("input", {});
    await vi.advanceTimersByTimeAsync(500);
    expect(t.requests).toHaveLength(1);
    const sent = t.paramsOf(t.requests[0]!.url);
    expect(sent.params.get("q")).toBe("raid");
    expect(sent.params.get("past")).toBe("1");
    expect(sent.params.get("view")).toBeNull();
    expect(sent.params.get("month")).toBeNull();
  });
});
